/// The kind of a piece of trivia: whitespace and comments around tokens.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum TriviaKind {
    WhiteSpace,
    EndOfLine,
    DelimitedComment,
    SingleLineComment,
    FixMe,
    Ignore,
    IgnoreError,
    FallThrough,
    ExtraTokenError,
}
